// Generates src/react.ts: React 18 wrappers around the Lit custom elements
// using @lit/react's createComponent. Run with `npm run generate:react`.
//
// This exists so the design system can be consumed as React components
// (required by Figma Make). It scans the component register files for
// `customElements.define('asm-x', AsmX)` calls and emits one wrapper per
// element, plus wrappers for the dynamically-registered typescale text
// elements. Do not edit src/react.ts by hand — edit this generator instead.

import { readdirSync, readFileSync, writeFileSync, statSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const SRC = join(__dirname, '..', 'src');
const COMPONENTS_DIR = join(SRC, 'components');
const OUT_FILE = join(SRC, 'react.ts');

// Custom events emitted by each element (tag -> DOM event names). Keep in sync
// with `dispatchEvent(new CustomEvent(...))` calls in the *.component.ts files.
const EVENTS = {
  'asm-accordion-item': ['toggle'],
  'asm-alert-banner': ['action', 'close'],
  'asm-calendar': ['change', 'range-change', 'confirm', 'cancel', 'clear'],
  'asm-card': ['card-click'],
  'asm-checkbox': ['change'],
  'asm-date-input': ['change', 'range-change'],
  'asm-feedback': ['thumbs-up', 'thumbs-down'],
  'asm-list-item': ['press'],
  'asm-modal': ['close'],
  'asm-nav-drawer': ['item-click'],
  'asm-navigation-rail-item': ['item-click', 'toggle-start', 'toggle-end'],
  'asm-navigation-rail': ['brand-click'],
  'asm-pagination': ['page-change'],
  'asm-phoneput': ['change'],
  'asm-radio': ['change'],
  'asm-snackbar': ['action', 'close'],
  'asm-split-button': ['action', 'toggle'],
  'asm-switch': ['change'],
  'asm-tab-group': ['tab-change'],
  'asm-tab': ['tab-select'],
  'asm-tag': ['close'],
  'asm-text-field': ['input', 'change'],
  'asm-toggle-group': ['change'],
  'asm-topbar': ['left-press', 'right-press', 'press'],
};

/** Convert a kebab tag/event to PascalCase (asm-nav-drawer -> AsmNavDrawer). */
function pascal(kebab) {
  return kebab
    .split('-')
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');
}

/** Convert a DOM event name to a React handler prop (range-change -> onRangeChange). */
function eventProp(eventName) {
  return 'on' + pascal(eventName);
}

/** Recursively collect all .ts register files (excluding *.component.ts / *.styles.ts). */
function collectRegisterFiles(dir) {
  const out = [];
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) {
      out.push(...collectRegisterFiles(full));
    } else if (
      name.endsWith('.ts') &&
      !name.endsWith('.component.ts') &&
      !name.endsWith('.styles.ts')
    ) {
      out.push(full);
    }
  }
  return out;
}

const DEFINE_RE = /customElements\.define\(\s*'([a-z][a-z0-9-]*)'\s*,\s*(\w+)\s*\)/g;

// { tag, className } for every statically-registered element.
const elements = [];
for (const file of collectRegisterFiles(COMPONENTS_DIR)) {
  const source = readFileSync(file, 'utf8');
  let match;
  while ((match = DEFINE_RE.exec(source)) !== null) {
    elements.push({ tag: match[1], className: match[2] });
  }
}
elements.sort((a, b) => a.tag.localeCompare(b.tag));

// Typescale text variants are registered dynamically in text/text.ts.
const textSource = readFileSync(join(COMPONENTS_DIR, 'text', 'text.ts'), 'utf8');
const variantsBlock = textSource.match(/const variants = \[([\s\S]*?)\] as const/);
const textVariants = variantsBlock
  ? [...variantsBlock[1].matchAll(/'([a-z][a-z0-9-]*)'/g)].map((m) => m[1])
  : [];

function renderEvents(tag) {
  const events = EVENTS[tag];
  if (!events || events.length === 0) return '';
  const entries = events.map((e) => `    ${eventProp(e)}: '${e}',`).join('\n');
  return `\n  events: {\n${entries}\n  },`;
}

const header = `// AUTO-GENERATED by scripts/generate-react-wrappers.mjs — do not edit by hand.
// Run \`npm run generate:react\` to regenerate.
//
// React 18 wrappers around the Assemble Lit custom elements, for consumers
// (such as Figma Make) that need React components instead of raw custom
// elements. Import from '@mcafee-eng/assemble/react'.
import * as React from 'react';
import { createComponent } from '@lit/react';
import * as Elements from './index.js';

// Re-export the design token stylesheet path helper is handled by package exports.
`;

const elementBlocks = elements
  .map(({ tag, className }) => {
    return `export const ${className} = createComponent({
  react: React,
  tagName: '${tag}',
  elementClass: Elements.${className},${renderEvents(tag)}
});`;
  })
  .join('\n\n');

const textBlocks = textVariants
  .map((variant) => {
    const tag = `asm-${variant}`;
    const name = pascal(tag);
    return `export const ${name} = createComponent({
  react: React,
  tagName: '${tag}',
  elementClass: Elements.AsmTextElements['${tag}'],
});`;
  })
  .join('\n\n');

const output = `${header}
${elementBlocks}

// Typescale text elements (registered dynamically in components/text/text.ts).
${textBlocks}
`;

writeFileSync(OUT_FILE, output, 'utf8');
console.log(
  `Generated ${OUT_FILE} with ${elements.length} element wrappers + ${textVariants.length} text wrappers.`,
);
